static void icon_render_rgba(uint8_t *rgba, int size) {
    if (!rgba || size < 1 || size > 4096) return;
    const unsigned char *data = app_icon_256;
    int source_size = 256;
    switch (size) {
    case 16: data = app_icon_16; source_size = 16; break;
    case 24: data = app_icon_24; source_size = 24; break;
    case 32: data = app_icon_32; source_size = 32; break;
    case 48: data = app_icon_48; source_size = 48; break;
    case 64: data = app_icon_64; source_size = 64; break;
    case 128: data = app_icon_128; source_size = 128; break;
    case 256: data = app_icon_256; source_size = 256; break;
    }
    size_t count = (size_t)source_size * source_size;
    uint8_t *pixels = size == source_size ? rgba : (uint8_t *)malloc(count * 4);
    if (!pixels) { memset(rgba, 0, (size_t)size * size * 4); return; }
    size_t pos = 0;
    while (pos < count) {
        unsigned token = *data++;
        size_t run = (token & 127) + 1;
        if (token & 128) {
            for (size_t i = 0; i < run; ++i) memcpy(pixels + (pos+i)*4, data, 4);
            data += 4;
        } else {
            memcpy(pixels + pos*4, data, run*4);
            data += run*4;
        }
        pos += run;
    }
    if (pixels != rgba) {
        /* Compatibility for unusual sizes. Bundle artwork uses full-resolution PNGs. */
        for (int y = 0; y < size; ++y) for (int x = 0; x < size; ++x)
            memcpy(rgba + ((size_t)y*size+x)*4,
                   pixels + ((size_t)(y*source_size/size)*source_size+x*source_size/size)*4, 4);
        free(pixels);
    }
}
